    def dfs(current, path):
        if current == goal:
            return path + [current]  # Return the path including the goal node
        path.append(current)
        for neighbor in graph.get(current, []):
            if neighbor not in path:
                new_path = dfs(neighbor, path.copy())  # Use path.copy() to avoid side effects
                if new_path:
